import * as THREE from 'three/webgpu';
import { tsl, mix, uv, position, mul, add, sub, abs, pow, sin, cos, fract, vec3, vec4, texture, vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import { createMsdfMesh } from '@/text';

export default function createNode(config, ctx) {
  const root = new THREE.Object3D();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // ---------- Background Plate ----------
  const plateWidth = 7;
  const plateHeight = 5.5;
  const plateGeometry = new THREE.PlaneGeometry(plateWidth, plateHeight);
  const gradStart = new THREE.Color('#0b0b10');
  const gradEnd = new THREE.Color('#14141a');
  const accentColor = new THREE.Color('#ff2a38');

  // Gradient + grain node material
  const uvNode = uv().xy;
  const gradientNode = mix(
    vec3(gradStart.r, gradStart.g, gradStart.b),
    vec3(gradEnd.r, gradEnd.g, gradEnd.b),
    uvNode.y
  );

  // Simple grain using noise
  const grainScale = 0.015;
  const grainNode = mul(
    sin(mul(uvNode, vec2(100.0))).x,
    grainScale
  );

  const bgColorNode = add(gradientNode, grainNode);
  const bgMaterial = new THREE.MeshBasicNodeMaterial({
    color: bgColorNode
  });

  const bgMesh = new THREE.Mesh(plateGeometry, bgMaterial);
  bgMesh.position.set(0, 0, 0);
  root.add(bgMesh);

  // ---------- Text Elements ----------
  const leftX = -3.1;
  const baseline = 0.25; // grid step

  // Helper to create a text mesh
  function addText({ string, family, weight, sizePx, letterSpacing, lineHeight, y, uppercase, color, duplicateShadow }) {
    const textMesh = createMsdfMesh({
      text: uppercase ? string.toUpperCase() : string,
      fontFamily: family,
      fontWeight: weight,
      fontSize: sizePx,
      letterSpacing,
      lineHeight,
      color,
      atlas: ctx.fontAtlas,
      atlasRegion: config.atlasRegion // use provided atlas region
    });

    textMesh.position.set(leftX, y, 0);
    root.add(textMesh);

    if (duplicateShadow) {
      const shadow = textMesh.clone();
      shadow.position.z -= 0.02; // push back
      shadow.material = shadow.material.clone();
      // tint shadow to ink color
      if (shadow.material.isNodeMaterial) {
        const inkColor = new THREE.Color('#16161d');
        const tintNode = mul(shadow.material.color, vec3(inkColor.r, inkColor.g, inkColor.b));
        shadow.material.color = tintNode;
      } else {
        shadow.material.color.set('#16161d');
      }
      root.add(shadow);
    }

    return textMesh;
  }

  // Kicker
  const kicker = addText({
    string: 'NOVA ATELIER / JOURNAL',
    family: 'JetBrains Mono',
    weight: 700,
    sizePx: 18,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    y: 1.7,
    uppercase: true,
    color: '#16161d'
  });

  // Hero line 1
  const hero1 = addText({
    string: 'PRECISION IS',
    family: 'Lora',
    weight: 600,
    sizePx: 124,
    letterSpacing: -0.015,
    lineHeight: 0.98,
    y: 0.9,
    uppercase: false,
    color: '#16161d',
    duplicateShadow: true
  });

  // Hero line 2
  const hero2 = addText({
    string: 'A HABIT.',
    family: 'Lora',
    weight: 600,
    sizePx: 124,
    letterSpacing: -0.015,
    lineHeight: 0.98,
    y: 0.25,
    uppercase: false,
    color: '#16161d',
    duplicateShadow: true
  });

  // Body
  const body = addText({
    string: 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
    family: 'JetBrains Mono',
    weight: 400,
    sizePx: 26,
    letterSpacing: 0,
    lineHeight: 1.55,
    y: -0.8,
    uppercase: false,
    color: '#16161d'
  });

  // Caption
  const caption = addText({
    string: 'ISSUE 12 / JULY 2026',
    family: 'JetBrains Mono',
    weight: 400,
    sizePx: 18,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    y: -1.9,
    uppercase: false,
    color: '#16161d'
  });

  // ---------- Underline Rule ----------
  const ruleWidth = 2.2;
  const ruleHeight = 0.05;
  const ruleGeometry = new THREE.PlaneGeometry(ruleWidth, ruleHeight);
  const ruleMaterial = new THREE.MeshBasicNodeMaterial({
    color: vec3(accentColor.r, accentColor.g, accentColor.b),
    emissive: vec3(accentColor.r, accentColor.g, accentColor.b).multiplyScalar(1.2)
  });
  const ruleMesh = new THREE.Mesh(ruleGeometry, ruleMaterial);
  ruleMesh.position.set(leftX + ruleWidth / 2, -0.15, 0);
  ruleMesh.scale.set(0, 1, 1); // start collapsed
  root.add(ruleMesh);

  // ---------- Animations ----------
  const timeline = gsap.timeline({ defaults: { ease: 'power3.out' } });

  const blocks = [
    { obj: kicker, yStart: kicker.position.y + 0.4 },
    { obj: hero1, yStart: hero1.position.y + 0.4 },
    { obj: hero2, yStart: hero2.position.y + 0.4 },
    { obj: body, yStart: body.position.y + 0.4 },
    { obj: caption, yStart: caption.position.y + 0.4 }
  ];

  blocks.forEach((blk, i) => {
    blk.obj.position.y = blk.yStart;
    blk.obj.material.opacity = 0;
    timeline.to(
      blk.obj.position,
      { y: blk.obj.position.y - 0.4, duration: 0.7 },
      i * 0.08
    );
    timeline.to(
      blk.obj.material,
      { opacity: 1, duration: 0.7 },
      i * 0.08
    );
  });

  // Underline after both hero lines have finished
  const heroEndTime = 0.08 * 2 + 0.7; // after hero2 rise-in
  timeline.to(
    ruleMesh.scale,
    { x: 1, duration: 0.5, ease: 'power2.out' },
    heroEndTime
  );

  // ---------- Cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timeline.kill();
    bgGeometry.dispose();
    plateGeometry.dispose();
    ruleGeometry.dispose();
    bgMaterial.dispose();
    ruleMaterial.dispose();
    // dispose text meshes (assumed they have dispose method)
    [kicker, hero1, hero2, body, caption].forEach(m => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) m.material.dispose();
    });
  };

  return root;
}
